import {photos,niches,videos,services,gallery,socials} from './content.js';
export const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function photo(key,sizes='(min-width: 900px) 35vw, 80vw',className=''){
 const p=photos[key];
 if(!p)return `<img class="${className}" src="${esc(key)}" alt="" loading="lazy" width="900" height="1200">`;
 return `<img class="${className}" src="/assets/photos/liza-${p.id}-960.webp" srcset="/assets/photos/liza-${p.id}-480.webp 480w, /assets/photos/liza-${p.id}-960.webp 960w, /assets/photos/liza-${p.id}-1440.webp 1440w" sizes="${sizes}" width="900" height="1200" loading="lazy" decoding="async" alt="${esc(p.alt)}">`;
}
const label=(n,name)=>`<p class="eyebrow micro">${n} / ${name}</p>`;
function About(){return `<section class="about section" id="about"><div class="wrap about-grid"><div class="about-heading">${label('01','Обо мне')}<h2>Привет,<br>я Лиза.</h2><p class="handwritten">давайте чуть ближе</p></div><figure class="about-portrait">${photo('summer')}<span class="tape" aria-hidden="true"></span><figcaption class="micro">ИЗ МОЕГО ФОТОДНЕВНИКА</figcaption></figure><div class="about-paper paper"><p class="about-lead">Я Лиза — лайфстайл<br>и UGC-креатор.</p><p>Создаю живой, эстетичный и нативный контент о красоте, стиле, повседневной жизни и маленьких вещах, которые делают её интереснее.</p><p>Мне важно, чтобы реклама не выбивалась из контента, а становилась его естественной частью. Поэтому я стараюсь не просто показать продукт, а придумать историю и подачу, через которые он действительно заинтересует аудиторию.</p><span class="paper-number micro">ЗАМЕТКА 001</span></div><blockquote class="about-quote"><span>Мой стиль — эстетика,<br>естественность,</span><strong class="handwritten">ощущение разговора<br>с подругой.</strong></blockquote></div><div class="bridge-film film" aria-hidden="true">${['beauty','street','cafe','mirror','flowers','summer','portrait','fashion'].map(k=>photo(k,'160px')).join('')}<span class="micro">BEAUTY / FASHION / LIFE</span></div></section>`}
function Contents(){return `<section class="contents section" id="contents"><div class="wrap record-layout"><div class="record-heading">${label('02','Внутри портфолио')}<h2>Поставим<br>на <span class="handwritten">повтор?</span></h2><p>То, что мне близко.<br>И то, что я создаю.</p></div><div class="record-object"><div class="record-sleeve"><span class="micro">ЛИЧНАЯ КОЛЛЕКЦИЯ</span><span class="sleeve-name">Лиза</span><span class="micro">LIFESTYLE / BEAUTY / FASHION</span></div><div class="record-lift"><div class="record-spin"><img class="record" src="/assets/vinyl.webp" width="1100" height="1100" loading="lazy" alt="Розовая виниловая пластинка"><span class="record-mark micro">LIZA<br>SIDE A<br>33⅓ RPM</span></div></div></div><nav class="tracklist" aria-label="Разделы портфолио">${[['about','Обо мне','ЗНАКОМСТВО'],['niches','Направления','МОЙ МИР'],['work','Работы','СМОТРЕТЬ'],['contact','Контакты','НА СВЯЗИ']].map(([id,name,note],i)=>`<a href="#${id}"><span class="micro">0${i+1}</span><span>${name}</span><small class="micro">${note}</small></a>`).join('')}</nav></div></section>`}
function Niches(){return `<section class="niches section" id="niches"><div class="wrap">${label('03','Мой мир')}<div class="directions-title"><h2>Мои направления</h2><span class="handwritten">разные истории — одна я</span></div><div class="directions-map"><svg class="niche-connections" viewBox="0 0 1000 650" preserveAspectRatio="none" aria-hidden="true"><path d="M430 240 C380 210 350 150 310 150 M430 330 C375 350 365 405 310 405 M575 240 C640 190 665 165 690 165 M575 330 C635 355 660 405 690 405 M500 380 C515 420 490 445 500 500"/></svg><figure class="niche-portrait"><div class="lace-portrait">${photo('beauty','(min-width: 900px) 28vw, 65vw','niche-face')}<img class="lace-frame" src="/assets/lace-frame.webp" width="900" height="1200" alt="" loading="lazy" aria-hidden="true"></div><figcaption class="handwritten">мой маленький мир</figcaption></figure>${niches.map((n,i)=>`<article class="niche-orbit orbit-${n.name.toLowerCase()}"><div class="orbit-photo"><img src="/assets/niches/${n.name.toLowerCase()}.webp" alt="${esc(n.imageAlt)}" width="480" height="600" loading="lazy" decoding="async"></div><div class="orbit-copy"><h3>${n.name}</h3><p>${esc(n.description)}</p></div></article>`).join('')}</div></div></section>`}
function Work(){return `<section class="work section" id="work"><div class="wrap">${label('04','Работы / Selected UGC')}<div class="work-heading"><h2>Смотреть.<br>Чувствовать.</h2><p class="handwritten">ещё один кадр,<br>и ещё один…</p></div>${videos.some(v=>!v.src)?'<p class="work-draft">Здесь скоро появятся 12 видео.<br>Пока — кадры Лизы и превью будущих работ.</p>':''}<div class="reels-wall"><div class="wall-label micro">КОНТАКТНЫЙ ЛИСТ / 001</div><div class="video-grid">${videos.map((v,i)=>`<article class="video-card"><div class="video-mount"><button class="video-preview" data-video="${i}" aria-label="${esc(v.title)}${v.src?' — смотреть видео':' — открыть превью'}">${photo(v.poster,'(min-width: 900px) 22vw, 30vw')}<span class="video-number micro">${v.id}</span><span class="play-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M9 5 20 12 9 19Z"/></svg></span>${!v.src?'<span class="video-soon">СКОРО</span>':''}</button></div><h3>${esc(v.title)}</h3><p>${esc(v.category)}</p></article>`).join('')}</div></div><p class="work-bottom handwritten">маленькие истории, которые хочется досмотреть</p></div></section>`}
function Contact(){return `<section class="contact section" id="contact"><div class="wrap"><div class="contact-letter paper"><div class="letter-top"><span class="micro">КОМУ: ВАШЕМУ БРЕНДУ<br>ОТ: ЛИЗЫ</span><span class="postage" aria-hidden="true">L.<small>CONTENT<br>WITH LOVE</small></span></div>${label('05','Связаться со мной')}<h2>Давайте создадим<br>что-то классное.</h2><div class="contact-body"><div><p>Готова к сотрудничеству с брендами в нишах бьюти, фешн и лайфстайл.</p><p>Если вам близка моя эстетика и формат контента — буду рада обсудить сотрудничество.</p><div class="social-links">${socials.map(s=>`<a href="${s.href}" ${s.href.startsWith('http')?'target="_blank" rel="noopener noreferrer"':''}><span class="micro">${s.name}</span><span>${s.label}</span></a>`).join('')}</div></div><figure class="contact-photo">${photo('portrait')}<figcaption class="handwritten">на связи,<br>Лиза</figcaption><span class="tape" aria-hidden="true"></span></figure></div><p class="letter-sign handwritten">начнём с вашего сообщения.</p></div><footer><a href="#home" class="wordmark">Л.</a><span class="micro">LIFESTYLE CREATOR & UGC</span><a href="#home">Наверх</a><button id="replay-intro">Открыть письмо</button></footer></div></section>`}
export function mountSections(target){target.innerHTML=[About(),Contents(),Niches(),Work(),Contact()].join('')}
